def Q(q, o, a, hw, ch, qz, oz, e, fig=None):
    d = {"q": q, "o": o, "a": a, "hw": hw, "ch": ch, "qz": qz, "oz": oz, "e": e}
    if fig:
        d["fig"] = fig
    return d

